<style>
:root{font-family:Inter,ui-sans-serif,system-ui,sans-serif;color:#193e35;background:#f5f4ed;font-synthesis:none}*{box-sizing:border-box}body{margin:0}a{color:#215d4a;text-underline-offset:4px}main{max-width:1160px;margin:auto;padding:36px 28px 70px}header{border-bottom:1px solid #d8ded3;padding-bottom:28px;margin-bottom:28px}h1{font-family:Georgia,serif;font-weight:400;font-size:clamp(32px,5vw,57px);line-height:1.09;max-width:850px;margin:14px 0 20px;letter-spacing:-1.5px}h2{font-size:23px;margin:6px 0 16px}h3{font-size:18px;margin:8px 0}p{line-height:1.65}small,.muted{color:#58675f;font-size:14px}.eyebrow{text-transform:uppercase;letter-spacing:2px;font-size:11px;font-weight:700}.pill{display:inline-block;font-size:12px;background:#e6ecdd;border:1px solid #cdd9c7;padding:5px 10px;border-radius:30px}.notice{padding:16px 20px;border:1px solid #d8cda7;background:#fbf7e9;border-radius:10px;margin:18px 0}.card{padding:24px;border:1px solid #d8ded3;background:#fffefa;border-radius:15px;margin:18px 0;overflow-wrap:anywhere}.grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.grid>.card{margin:0}.actions{display:flex;gap:12px;align-items:center;flex-wrap:wrap}button,.button{display:inline-flex;align-items:center;justify-content:center;min-height:46px;padding:12px 18px;border:1px solid #1c4c3f;border-radius:8px;background:#1c4c3f;color:#fff;text-decoration:none;font:600 14px system-ui;cursor:pointer}.secondary{background:transparent;color:#214f40}.danger{background:transparent;color:#80442d;border-color:#c5b9a9}label{display:block;font-size:14px;font-weight:600;margin:16px 0 7px}input,textarea,select{font:inherit;color:inherit;width:100%;min-height:46px;border:1px solid #b8c5ba;border-radius:7px;background:white;padding:10px}input[type=checkbox],input[type=radio]{width:21px;min-height:21px;vertical-align:middle;margin:0 9px 0 0;accent-color:#245542}input:focus,textarea:focus,select:focus,a:focus,button:focus{outline:3px solid #a0bb89;outline-offset:3px}textarea{resize:vertical}.row{display:flex;justify-content:space-between;gap:20px;border-top:1px solid #e1e5dc;padding:13px 0}.price{white-space:nowrap;font-family:Georgia,serif;font-size:32px;letter-spacing:-1px}.price small{font:14px system-ui;letter-spacing:0}.body-copy{white-space:pre-line;max-width:850px}.bounded{max-width:520px;margin:10vh auto}.hash{font:11px/1.5 monospace;overflow-wrap:anywhere}.term-options{display:flex;gap:18px;flex-wrap:wrap}.term-options label{font-weight:400}.topline{display:flex;justify-content:space-between;gap:20px;align-items:center}.brand{font-size:15px;letter-spacing:.5px}.brand-mark{display:inline-block;width:17px;height:17px;border-radius:3px 12px 3px 12px;background:#507653;margin-right:8px;vertical-align:middle}details>summary{cursor:pointer;font-weight:600;padding:8px 0;min-height:42px}form{margin:0}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%}th,td{text-align:left;vertical-align:top;padding:14px 10px;border-bottom:1px solid #e0e4d9;min-width:110px}th{font-size:12px;text-transform:uppercase;letter-spacing:1px}.money{text-align:right;white-space:nowrap}footer{margin-top:34px;font-size:13px;color:#657267}nav{margin:15px 0}hr{border:0;border-top:1px solid #d8ded3;margin:24px 0}@media(max-width:720px){main{padding:24px 18px 50px}.grid{grid-template-columns:1fr}h1{letter-spacing:-.7px}.card{padding:20px}.topline{align-items:flex-start}.actions>*{flex-grow:1}.bounded{margin:8vh 0}}@media print{.actions,button,nav,.no-print{display:none!important}body{background:white}main{padding:0}.card{break-inside:avoid}.grid{display:block}h1{font-size:36px}}
.journey{margin:64px 0 58px;padding-top:34px;border-top:1px solid #d2dccc}.journey-intro{max-width:780px}.journey-intro h2{font-size:18px;letter-spacing:.1px}.journey-lead{font:400 clamp(30px,4.2vw,47px)/1.15 Georgia,serif;letter-spacing:-.9px;margin:21px 0}.journey-intro>p:last-child{color:#4c6053;max-width:730px}.journey-overview{margin:28px 0 42px}.journey-landscape{display:block;width:100%;height:auto;max-height:190px}.journey-overview-stages{list-style:none;padding:0;margin:0;display:flex;justify-content:space-between;gap:18px;border-bottom:1px solid #d2dccc;padding-bottom:28px}.journey-overview-stages li{font-size:14px;color:#34503c;flex:1;min-width:0}.journey-overview-stages span{font:15px Georgia,serif;display:block;margin-bottom:7px;color:#536b46}.journey-path{list-style:none;padding:0;margin:0 0 0 5px}.journey-path>li{position:relative;padding:18px 20px 48px 150px;min-height:330px}.journey-trail{position:absolute;left:0;top:42px;width:120px;height:100%;pointer-events:none}.journey-step{position:absolute;left:38px;top:20px;background:#f5f4ed;color:#526d43;border:1px solid #a5b895;border-radius:50%;width:44px;height:44px;display:grid;place-items:center;font:19px Georgia,serif;box-shadow:0 0 0 7px #f5f4ed}.journey-phase{max-width:780px;padding:0}.journey-phase>.eyebrow{font-size:10px;letter-spacing:1.8px;margin:2px 0 13px;color:#56704c}.journey-phase h3{font:400 clamp(25px,3vw,34px)/1.18 Georgia,serif;letter-spacing:-.5px;margin:0 0 16px;max-width:680px}.journey-body{margin:0 0 17px;max-width:690px;color:#3b5545}.journey-detail{display:grid;grid-template-columns:1fr 1fr;gap:32px;font-size:14px;max-width:690px}.journey-detail p{margin:5px 0 17px;color:#53624f}.journey-detail strong,.journey-gate strong{font-size:10px;text-transform:uppercase;letter-spacing:1px;color:#536b46}.journey-gate{font-size:13px;line-height:1.7;padding:13px 0 0;border-top:1px solid #d9e0d0;color:#52634b;max-width:690px;margin:0}.journey-gate strong{display:block;margin-bottom:6px}.journey-end{margin:0 0 0 43px;display:flex;align-items:flex-start;gap:27px;border-top:1px solid #d2dccc;padding-top:27px;max-width:900px}.journey-end svg{width:38px;height:45px;flex-shrink:0}.journey-end p{font:italic 17px/1.65 Georgia,serif;color:#53634a;margin:0;max-width:720px}@media(min-width:1000px){.journey-path>li:nth-child(even) .journey-phase{margin-left:65px}.journey-path>li:nth-child(even){padding-bottom:54px}}@media(max-width:760px){.journey{margin-top:44px;padding-top:26px}.journey-lead{letter-spacing:-.5px}.journey-overview{margin:16px 0 30px}.journey-overview-stages{gap:12px;flex-wrap:wrap;padding:10px 0 20px}.journey-overview-stages li{flex:0 0 calc(33.333% - 8px);font-size:13px}.journey-overview-stages span{display:inline;margin-right:7px;font-size:13px}.journey-landscape{min-height:80px;object-fit:cover}.journey-path{margin-left:0}.journey-path>li{padding:15px 0 38px 68px;min-height:0}.journey-trail{width:52px;left:0;top:35px}.journey-step{left:9px;top:18px;width:34px;height:34px;font-size:15px;box-shadow:0 0 0 5px #f5f4ed}.journey-phase h3{font-size:27px;line-height:1.2}.journey-body{font-size:15px;line-height:1.7}.journey-detail{grid-template-columns:1fr;gap:0;font-size:13px}.journey-detail p{margin-bottom:13px}.journey-gate{font-size:12px}.journey-end{margin-left:11px;gap:24px;padding-top:21px}.journey-end svg{width:29px;height:38px}.journey-end p{font-size:16px}}@media print{.journey-path>li{break-inside:avoid}.journey-trail{display:none}.journey-path>li{padding-bottom:30px;min-height:0}.journey-landscape{max-height:120px}}
.department-story{margin:42px 0 54px;padding-top:27px;border-top:1px solid #d2dccc}.department-story>h3{font:400 clamp(26px,3vw,36px)/1.2 Georgia,serif;letter-spacing:-.5px;margin:12px 0 16px}.department-story-lead{max-width:750px;color:#4c6053}.network-caption{font-size:12px;color:#536b46;margin:25px 0 0}.network-illuminated{display:inline-block;width:9px;height:9px;background:#6f925a;border:1px solid #56754a;border-radius:50%;margin-right:8px;box-shadow:0 0 0 4px #e4ecd9}.department-network{width:100%;height:auto;display:block;margin:5px 0 20px}.network-mobile{display:none}.department-network text{font-family:ui-sans-serif,system-ui,sans-serif;fill:#34503c}.network-context-label{font-size:14px;letter-spacing:2px;fill:#586c4e!important}.network-department-label{font:400 25px Georgia,serif!important;fill:#2c5132!important}.network-status-label{font-size:17px;fill:#506c42!important}.network-node-label{font-size:18px;fill:#34553a!important}.network-hub-label{font-size:14px;fill:#fff!important}.network-link-label{font-size:17px;fill:#536b46!important;paint-order:stroke;stroke:#f5f4ed;stroke-width:7px;stroke-linejoin:round}.network-pending-title{font:400 21px Georgia,serif!important;fill:#52654a!important}.network-pending-label{font-size:17px;fill:#596e4d!important}.network-pending-note{font-size:14px;fill:#596e4d!important}.rollout-story{max-width:940px;padding:18px 0 0}.rollout-story h4{font:400 27px/1.25 Georgia,serif;letter-spacing:-.4px;margin:12px 0 27px}.rollout-sequence{list-style:none;display:flex;gap:28px;padding:0;margin:0 0 24px}.rollout-sequence li{flex:1;border-top:1px solid #bdcdae;padding:17px 0 0;min-width:0}.rollout-sequence span{font:20px Georgia,serif;color:#5a774a;display:block;margin-bottom:12px}.rollout-sequence strong{font-size:14px;font-weight:600;display:block;line-height:1.6;color:#3b5540}.rollout-sequence small{display:block;font-size:13px;line-height:1.7;margin-top:6px;color:#596b50}.rollout-gate{font-size:14px;color:#4b6144;max-width:850px;